 const title=page==='Overview'?'Good morning':page
 function stat(icon:LucideIcon,label:string,value:string,detail:string,positive=true,action?:()=>void){const I=icon;return <div className={`stat-card ${action?'stat-card-clickable':''}`} role={action?'button':undefined} tabIndex={action?0:undefined} aria-label={action?`${label}: ${value}. View details`:undefined} onClick={action} onKeyDown={e=>{if(action&&(e.key==='Enter'||e.key===' ')){e.preventDefault();action()}}}><div className="stat-head"><span>{label}</span><span className="stat-icon"><I size={17}/></span></div><div className="stat-value">{value}</div><div className={`stat-foot ${positive?'':'amber-note'}`}>{!positive&&<AlertTriangle size={11}/>}<span>{detail}</span>{action&&<ArrowRight className="stat-open-icon" size={14}/>}</div></div>}
