 function productTable(){return <div className="table-wrap"><table><thead><tr><th><input type="checkbox" checked={visible.length>0&&selected.length===visible.length} onChange={()=>setSelected(selected.length===visible.length?[]:visible.map((p:Product)=>p.id))}/></th><th>PRODUCT</th><th>SKU / BARCODE</th><th>CATEGORY</th>{currencyEnabled.LKR&&<th>PRICE · LKR</th>}{currencyEnabled.CHF&&<th>PRICE · CHF</th>}<th>STATUS</th><th></th></tr></thead><tbody>{visible.map((p:Product)=><tr key={p.id}><td><input type="checkbox" checked={selected.includes(p.id)} onChange={()=>setSelected(selected.includes(p.id)?selected.filter(x=>x!==p.id):[...selected,p.id])}/></td><td><div className="product-name"><div className="product-thumb">{p.image?<img src={p.image}/>:<Package size={17}/>}</div><div><strong>{p.name}</strong><span>{p.brand||`${p.weight} ${p.unit}`}</span></div></div></td><td><span className="code">{p.sku}</span><span className="subcode">{p.barcode}</span></td><td>{p.category}</td>{currencyEnabled.LKR&&<td className="amount">{money(Number(p.priceLkr),'LKR')}</td>}{currencyEnabled.CHF&&<td className="amount">{money(Number(p.priceChf),'CHF')}</td>}<td><span className={`badge ${p.status==='Active'?'active':'inactive'}`}><i/> {p.status}</span></td><td><div className="row-actions"><button title="Add to print queue" onClick={()=>addToPrintQueue([p])}><Printer size={15}/></button><button title="Duplicate" onClick={()=>duplicate(p)}><Copy size={16}/></button><button title="Edit" onClick={()=>{setEdit(p);setModal('product')}}><Pencil size={14}/></button><button title="Delete" onClick={()=>removeProduct(p.id)}><Trash2 size={14}/></button></div></td></tr>)}</tbody></table>{!visible.length&&empty('Nothing here yet',query?'Try a different search or clear your filters.':'Your first product is just a few details away.','Add product',openNew)}</div>}
 if(authStatus==='checking')return <div className="auth-screen"><div className="auth-card"><div className="brand-mark"><Barcode size={23}/></div><h1>Connecting to your database</h1><p>Checking the secure session and loading saved workspace data.</p></div></div>
 if(authStatus==='unavailable')return <div className="auth-screen"><div className="auth-card"><div className="auth-error-icon"><AlertTriangle size={22}/></div><h1>Database unavailable</h1><p>{authError}</p><button className="btn primary" onClick={()=>{setAuthStatus('checking');void loadDatabase().catch((error:any)=>{setAuthStatus(error?.response?.status===401?'login':'unavailable');setAuthError(error?.response?.data?.error||'Cannot connect to the database API.')})}}>Try again</button><small>Configure PostgreSQL and the administrator account using the steps in README.md.</small></div></div>
